mutation SetCustomFieldValue(
  $entityType: String!
  $entityId: ID!
  $key: String!
  $value: CustomFieldValueInput!
) {
  setCustomFieldValue(input: { entityType: $entityType, entityId: $entityId, key: $key, value: $value }) {
    value {
      key
      fieldVersion
