mutation CreateCustomField(
  $entity: String!
  $key: String!
  $label: String!
  $fieldType: String!
  $dataClass: String
  $options: [CustomFieldOptionInput!]
) {
  createCustomField(
    input: {
      entity: $entity
      key: $key
      label: $label
      fieldType: $fieldType
      dataClass: $dataClass
      options: $options
    }
  ) {
    field {
      id
      key
      version
    }
    userErrors {
      code
      message
    }
  }
}

