query JobWorkspace($id: ID!, $after: String) {
  job(id: $id) {
    id
    title
    status
    openings
    confidential
    codeName
    version
    stages {
      key
      name
      type
    }
    applications(first: 20, after: $after) {
      pageInfo {
        hasNextPage
        endCursor
      }
      nodes {
        id
        status
        currentStageKey
        version
        updatedAt
        createdAt
        person {
          id
          displayName
          primaryEmail
        }
        transitions {
          toStageKey
          createdAt
        }
        upcomingInterview {
          interviewKey
          stageKey
          startsAt
        }
      }
    }
  }
}

a51fa0ec20d1d7de40609ce1dfc06ac69d84efe8:
query PersonCustomFields($id: ID!) {
  person(id: $id) {
    id
    customFields {
      key
      fieldType
      fieldVersion
      definition {
        label
      }
      ... on CustomFieldTextValue {
        text
      }
      ... on CustomFieldNumberValue {
        number
      }
      ... on CustomFieldDateValue {
        date
      }
      ... on CustomFieldBooleanValue {
        boolean
      }
      ... on CustomFieldOptionValue {
        option
      }
      ... on CustomFieldOptionsValue {
        options
      }
      ... on CustomFieldReferenceValue {
        referenceId
      }
    }
  }
}

